/* Beings: the list in three views (BN1, BN4) and the being page (BN2, BN3). */
const bnAv = (b, c = '') => `<span class="bn-av ${c}" aria-hidden="true">${esc(initials(b.name))}</span>`;
const bnAud = (a, who) => `<span class="bn-aud">${ic(a === 'GM only' ? 'private' : a === 'Everyone' ? 'eye' : a === 'Player note' ? 'kind-being' : 'visibility')}${esc(a)}${who && who.length ? `: ${esc(who.join(', '))}` : ''}</span>`;
const bnNum = (b, d) => { const v = statVal(b, d), m = statMax(b, d); return `<b class="num">${v}</b>${m != null ? `<span class="bn-max">/ ${m}</span>` : ''}`; };
/* ---------------------------------------------------------------- the list */
function listBar() {
  const kinds = ['All', 'Character', 'NPC'];
  return `<div class="head-row"><div class="grow"><h1 class="t-title page-title">${S.route === 'mine' ? 'My beings' : 'All beings'}</h1><p class="page-sub">The characters of ${esc(lib())}.</p></div>${isGM() ? `<button type="button" class="btn btn--primary" data-bn="new">${ic('add')}New being</button>` : ''}</div>
  <div class="toolbar bn-tools"><div class="search">${ic('search')}<label class="sr-only" for="bn-q">Search beings</label><input id="bn-q" class="input" type="search" placeholder="Search beings" value="${esc(BN.q)}" autocomplete="off"></div>
  <div class="seg" role="radiogroup" aria-label="Kind">${kinds.map((k) => `<button type="button" role="radio" aria-checked="${BN.kind === k}" data-bn="kind" data-v="${k}">${k === 'All' ? 'All kinds' : k}</button>`).join('')}</div>
  <span class="grow"></span>
  ${BN.view === 'side' ? `<div class="seg" role="radiogroup" aria-label="Mode">${[['read', 'Read', 'eye'], ['play', 'Play', 'play']].map(([k, t, i]) => `<button type="button" role="radio" aria-checked="${(BN.lplay ? 'play' : 'read') === k}" data-bn="lplay" data-v="${k}">${ic(i)}<span>${t}</span></button>`).join('')}</div>${BN.lplay ? `<button type="button" class="btn" data-bn="lundo" ${BN.hist.length ? '' : 'aria-disabled="true"'}>${ic('undo')}<span>Undo</span></button>` : ''}` : ''}
  <div class="seg" role="radiogroup" aria-label="View">${[['rows', 'Rows', 'list'], ['cards', 'Cards', 'layout-inspect'], ['side', 'Side by side', 'compare']].map(([k, t, i]) => `<button type="button" role="radio" aria-checked="${BN.view === k}" data-bn="view" data-v="${k}">${ic(i)}<span>${t}</span></button>`).join('')}</div></div>`;
}
function listBody() {
  const L = listBeings();
  if (!L.length) {
    if (BN.q || BN.kind !== 'All') return `<div class="bn-empty"><p><b>Nothing matches.</b></p><p class="t-meta">No being has “${esc(BN.q || BN.kind)}” in it that you can read.</p><button type="button" class="btn" data-bn="clear">Clear the search</button></div>`;
    return `<div class="bn-empty">${slot('empty-beings', 'No being yet')}<p><b>No being yet.</b></p><p class="t-meta">${isGM() ? 'Make the first one. It has no player until you hand it over.' : 'A GM makes a being, then hands it to a player.'}</p>${isGM() ? `<button type="button" class="btn btn--primary" data-bn="new">${ic('add')}New being</button>` : ''}</div>`;
  }
  const hp = statDef('hp'), arm = statDef('arm');
  if (BN.view === 'rows') return `<div role="table" aria-label="Beings" class="bn-lt"><div role="row" class="bn-lr bn-lh"><span role="columnheader">Name</span><span role="columnheader">Kind</span><span role="columnheader">Played by</span><span role="columnheader" class="r">Hit points</span><span role="columnheader" class="r">Armour</span></div>${L.map((b) => `<div role="row" class="bn-lr"><span role="cell" class="bn-nm">${bnAv(b, 'xs')}<a href="#/being/${b.id}">${esc(b.name)}</a>${b.seen !== 'Everyone' ? `<span class="bn-aud sm">${ic('private')}${esc(b.seen)}</span>` : ''}</span><span role="cell" class="muted">${b.kind}</span><span role="cell" class="muted">${esc(personName(b.played))}</span><span role="cell" class="r">${bnNum(b, hp)}</span><span role="cell" class="r num">${statVal(b, arm)}</span></div>`).join('')}</div>`;
  if (BN.view === 'cards') return `<ul class="bn-cg">${L.map((b) => `<li class="bn-card">${bnAv(b, 'lg')}<a href="#/being/${b.id}"><b>${esc(b.name)}</b></a><span class="t-meta">${b.kind}${b.played ? ` · ${esc(personName(b.played))}` : ''}</span><span class="bn-cn">${bnNum(b, hp)}<span class="t-meta">hit points</span></span></li>`).join('')}</ul>`;
  const rows = STATDEF.filter((d) => d.k === 'num');
  return `<div class="bn-sbs hmask" role="region" aria-label="Beings side by side" tabindex="0"><table class="bn-ds bn-sbt"><caption class="sr-only">Numbers of the beings, side by side</caption><thead><tr><th scope="col">Stat</th>${L.map((b) => `<th scope="col"><a href="#/being/${b.id}">${esc(b.name)}</a><span class="t-meta">${b.kind}</span></th>`).join('')}</tr></thead><tbody><tr><th scope="row">Played by</th>${L.map((b) => `<td>${esc(personName(b.played))}</td>`).join('')}</tr>${rows.map((d) => `<tr><th scope="row">${d.n}${d.derived ? ` <span class="bn-der" title="Derived">${ic('formula')}</span>` : ''}</th>${L.map((b) => `<td class="num">${statVal(b, d)}${statMax(b, d) != null ? ` / ${statMax(b, d)}` : ''}${BN.lplay && canRun(b) && !d.derived ? `<span class="bn-stp inl2"><button type="button" class="bn-sb" data-bn="step" data-b="${b.id}" data-v="${d.id}" data-d="-1" aria-label="Lower ${d.n} of ${esc(b.name)}">${ic('decrease')}</button><button type="button" class="bn-sb" data-bn="step" data-b="${b.id}" data-v="${d.id}" data-d="1" aria-label="Raise ${d.n} of ${esc(b.name)}">${ic('add')}</button></span>` : ''}</td>`).join('')}</tr>`).join('')}</tbody></table></div>`;
}
function pList() { return `<div class="page page--wide page-enter bn">${listBar()}<div id="bn-body" aria-live="off">${listBody()}</div></div>`; }
/* ---------------------------------------------------------------- the being page */
function bnTile(b, d, big) {
  const v = statVal(b, d), m = statMax(b, d); const run = BN.mode === 'play' && canRun(b) && !d.derived; const ed = BN.mode === 'read' && canEdit(b) && !d.derived && d.k === 'num';
  const editing = BN.editStat === d.id && ed; const adj = BN.adjustOpen === d.id && run;
  const head = `<div class="bn-tl"><span class="bn-tn">${d.n}${d.derived ? `<span class="sr-only"> (derived)</span>` : ''}</span>${d.derived ? `<button type="button" class="bn-why" data-bn="why" data-v="${d.id}" aria-label="Why is ${d.n} ${v}?" aria-expanded="${BN.why === d.id}" aria-controls="why-${d.id}">${ic('formula')}</button>` : ed ? `<button type="button" class="bn-why" data-bn="editstat" data-v="${d.id}" aria-label="${editing ? 'Done editing' : 'Edit'} ${d.n}" aria-pressed="${editing}">${ic(editing ? 'select-item' : 'edit')}</button>` : ''}</div>`;
  const val = editing ? `<div class="bn-ed"><label class="sr-only" for="v-${d.id}">${d.n}</label><input id="v-${d.id}" class="input" inputmode="numeric" data-stat="${d.id}" data-f="v" value="${v}">${m != null ? `<span>/</span><label class="sr-only" for="m-${d.id}">${d.n} limit</label><input id="m-${d.id}" class="input" inputmode="numeric" data-stat="${d.id}" data-f="max" value="${m}">` : ''}</div>` : run ? `<button type="button" class="bn-val" data-bn="adjust" data-v="${d.id}" aria-label="${v}${m != null ? ` / ${m}` : ''} ${d.n}. Change by an amount" aria-expanded="${adj}"><b class="num">${v}</b>${m != null ? `<span class="bn-max">/ ${m}</span>` : ''}</button>` : `<div class="bn-val ro"><b class="num">${v}</b>${m != null ? `<span class="bn-max">/ ${m}</span>` : ''}</div>`;
  const bar = m != null && !editing ? `<div class="bn-bar" aria-hidden="true"><i style="width:${Math.round((v / (m || 1)) * 100)}%"></i></div>` : '';
  const step = run && !adj ? `<span class="bn-stp" role="group" aria-label="Change ${d.n}"><button type="button" class="bn-sb" data-bn="step" data-b="${b.id}" data-v="${d.id}" data-d="-1" aria-label="Lower ${d.n}">${ic('decrease')}</button><button type="button" class="bn-sb" data-bn="step" data-b="${b.id}" data-v="${d.id}" data-d="1" aria-label="Raise ${d.n}">${ic('add')}</button></span>` : '';
  const adjf = adj ? `<div class="bn-adj"><label class="t-meta" for="a-${d.id}">Change by</label><div class="row2"><input id="a-${d.id}" class="input" inputmode="numeric" placeholder="-5, +3 or 12" data-adj="${d.id}"><button type="button" class="btn" data-bn="apply" data-v="${d.id}">Apply</button><button type="button" class="btn ghost" data-bn="adjust" data-v="${d.id}">Cancel</button></div></div>` : '';
  const why = d.derived && BN.why === d.id ? `<p class="bn-whyp t-meta" id="why-${d.id}">${ic('formula')}${esc(d.why(b))}. Derived: it cannot be set, only its parts.</p>` : '';
  const bp = BN.bump && BN.bump.b === b.id && BN.bump.id === d.id ? BN.bump : null;
  const delta = bp ? `<span class="bn-delta" aria-hidden="true">${bp.delta > 0 ? '+' : '\u2212'}${Math.abs(bp.delta)}</span>` : '';
  return `<div class="bn-tile ${d.derived ? 'derived' : ''} ${big ? 'big' : ''} ${bp ? 'bump' : ''}" role="group" aria-label="${d.n}">${head}${val}${delta}${bar}${step}${adjf}${why}</div>`;
}
const bnMode = () => `<div class="seg" role="radiogroup" aria-label="Mode"><button type="button" role="radio" aria-checked="${BN.mode === 'read'}" data-bn="mode" data-v="read">${ic('eye')}<span>Read</span></button><button type="button" role="radio" aria-checked="${BN.mode === 'play'}" data-bn="mode" data-v="play">${ic('play')}<span>Play</span></button></div>`;
const bnLayout = () => `<div class="seg sm" role="radiogroup" aria-label="Layout"><button type="button" role="radio" aria-checked="${BN.layout === 'sheet'}" data-bn="layout" data-v="sheet">Sheet</button><button type="button" role="radio" aria-checked="${BN.layout === 'data'}" data-bn="layout" data-v="data">Datasheet</button></div>`;
function bnHead(b) {
  return `<header class="bn-head">${bnAv(b, 'lg')}<div class="grow"><h1 class="t-title page-title" style="margin:0">${esc(b.name)}</h1><p class="t-meta" style="margin:0">${b.kind} · ${b.played ? `played by ${esc(personName(b.played))}` : 'not played'} · ${esc(b.place)}</p></div>${isGM() ? `<button type="button" class="icon-btn bn-more" data-bn="more" aria-label="More for ${esc(b.name)}" aria-haspopup="menu" aria-expanded="false">${ic('more')}</button>` : ''}</header>`;
}
function bnBar(b) {
  const l = bnHist(b); const play = BN.mode === 'play'; const run = canRun(b); const last = l[l.length - 1];
  const hint = play ? (run ? 'At the table. Numbers first; every change can be undone.' : 'At the table. Only its player and the GM change it.') : 'Reading. Edit a section where it is.';
  return `<div class="bn-bar2"><div class="bn-modewrap">${bnMode()}<span class="t-meta bn-modehint" id="bn-mh">${hint}</span></div>${play && run ? `<span class="bn-act"><button type="button" class="btn" data-bn="undo" ${last ? '' : 'aria-disabled="true"'}>${ic('undo')}<span>Undo</span>${last ? `<span class="t-meta bn-lastn">${esc(last.n)}</span>` : ''}</button><button type="button" class="btn" data-bn="history" aria-haspopup="menu" aria-expanded="false">${ic('history')}<span>History</span>${l.length ? `<span class="bn-cnt">${l.length}</span>` : ''}</button></span>` : ''}</div>`;
}
function bnBand(b) { const pins = STATDEF.filter((d) => d.pin); return `<div class="bn-sent" aria-hidden="true"></div><div class="bn-band ${BN.mode === 'play' ? 'play' : ''}" id="bn-band" role="group" aria-label="Mode and pinned numbers">${bnBar(b)}<div class="bn-pins">${pins.map((d) => bnTile(b, d, true)).join('')}</div></div>`; }
function bnAbout(b) {
  const ed = canEdit(b) && BN.mode === 'read';
  if (BN.mode === 'play') return `<details class="bn-sec bn-s-about"><summary class="t-sec">About</summary><p>${b.about ? esc(b.about) : '<span class="muted">Nothing written yet.</span>'}</p></details>`;
  return `<section class="bn-sec bn-s-about" aria-labelledby="h-ab"><div class="bn-sh"><h2 id="h-ab" class="t-sec">About</h2>${ed ? `<button type="button" class="btn ghost sm" data-bn="editabout" aria-pressed="${BN.editAbout}">${ic(BN.editAbout ? 'select-item' : 'edit')}<span>${BN.editAbout ? 'Done' : 'Edit'}</span></button>` : ''}</div>${BN.editAbout && ed ? `<div id="bn-about" class="bn-inl" contenteditable="true" role="textbox" aria-multiline="true" aria-label="About">${esc(b.about)}</div><p class="t-meta bn-sv" role="status">${ic('save')}<span id="bn-saved">${BN.saved || 'Changes are saved as you type.'}</span></p>` : `<p>${b.about ? esc(b.about) : '<span class="muted">Nothing written yet.</span>'}</p>`}</section>`;
}
function bnNotes(b) {
  const ed = canEdit(b) && BN.mode === 'read'; const L = visibleNotes(b);
  return `<section class="bn-sec bn-s-notes" aria-labelledby="h-no"><div class="bn-sh"><h2 id="h-no" class="t-sec">Notes</h2>${canEdit(b) ? `<button type="button" class="btn ghost sm" data-bn="addnote">${ic('add')}<span>Add a note</span></button>` : ''}</div>${L.length ? `<ul class="bn-notes">${L.map((n) => `<li>${bnAud(n.aud, n.who)}${BN.editNote === n.id ? `<textarea class="input bn-ta" data-note="${n.id}" aria-label="Note">${esc(n.t)}</textarea><div class="row2"><button type="button" class="btn" data-bn="notedone">Done</button></div>` : `<p>${esc(n.t)}</p>`}${ed && BN.editNote !== n.id ? `<button type="button" class="icon-btn sm bn-nm2" data-bn="notemenu" data-v="${n.id}" aria-label="Actions for the ${esc(n.aud)} note" aria-haspopup="menu" aria-expanded="false">${ic('more')}</button>` : ''}</li>`).join('')}</ul>` : '<p class="muted">No notes you can read.</p>'}</section>`;
}
function condRow(b) {
  const d = statDef('cond'); const on = b.stats.cond.v; const run = BN.mode === 'play' && canRun(b);
  if (run) return `<span class="bn-conds" role="group" aria-label="Conditions">${d.options.map((o) => `<button type="button" class="bn-cond" data-bn="cond" data-b="${b.id}" data-v="${o}" aria-pressed="${on.includes(o)}">${ic(on.includes(o) ? 'select-item' : 'add')}<span>${o}</span></button>`).join('')}</span>`;
  return on.length ? on.map((t) => `<span class="bn-tag">${esc(t)}</span>`).join(' ') : '<span class="muted">None</span>';
}
function bnStats(b) {
  const run = BN.mode === 'play' && canRun(b); const nums = STATDEF.filter((d) => d.k === 'num');
  let body;
  if (BN.layout === 'data') body = `<table class="bn-ds"><caption class="sr-only">Stats of ${esc(b.name)}</caption><thead><tr><th scope="col">Stat</th><th scope="col" class="r">Value</th><th scope="col">How</th></tr></thead><tbody>${nums.map((d) => `<tr><th scope="row">${d.n}</th><td class="r num">${statVal(b, d)}${statMax(b, d) != null ? ` / ${statMax(b, d)}` : ''}${run && !d.derived ? `<span class="bn-stp inl2"><button type="button" class="bn-sb" data-bn="step" data-b="${b.id}" data-v="${d.id}" data-d="-1" aria-label="Lower ${d.n}">${ic('decrease')}</button><button type="button" class="bn-sb" data-bn="step" data-b="${b.id}" data-v="${d.id}" data-d="1" aria-label="Raise ${d.n}">${ic('add')}</button></span>` : ''}</td><td class="t-meta">${d.derived ? `${ic('formula')}${esc(d.why(b))}` : 'set directly'}</td></tr>`).join('')}<tr><th scope="row">Conditions</th><td colspan="2">${condRow(b)}</td></tr><tr><th scope="row">Role</th><td colspan="2">${esc(b.stats.role.v)}</td></tr><tr><th scope="row">Languages</th><td colspan="2">${b.stats.langs.v.map((t) => `<span class="bn-tag">${esc(t)}</span>`).join(' ')}</td></tr></tbody></table>`;
  else body = `<div class="bn-tiles">${nums.filter((d) => !d.pin).map((d) => bnTile(b, d)).join('')}</div><dl class="bn-rows"><div><dt>Conditions</dt><dd>${condRow(b)}</dd></div><div><dt>Role</dt><dd>${esc(b.stats.role.v)}</dd></div><div><dt>Languages</dt><dd>${b.stats.langs.v.map((t) => `<span class="bn-tag">${esc(t)}</span>`).join(' ')}</dd></div></dl>`;
  return `<section class="bn-sec bn-s-stats" aria-labelledby="h-st"><div class="bn-sh"><h2 id="h-st" class="t-sec">Stats</h2>${bnLayout()}</div>${BN.layout === 'sheet' ? '<p class="t-meta bn-hint">Pinned numbers are in the band above. A dashed border means derived: it is worked out, not set.</p>' : ''}${body}</section>`;
}
const bnInv = (b) => `<section class="bn-sec bn-s-inv" aria-labelledby="h-in"><div class="bn-sh"><h2 id="h-in" class="t-sec">Inventory</h2></div>${b.inv.length ? `<ul class="bn-inv">${b.inv.map(([n, q]) => `<li>${ic('kind-item')}<span>${esc(n)}</span><span class="t-meta num">× ${q}</span></li>`).join('')}</ul>` : '<p class="muted">Carries nothing.</p>'}</section>`;
function bnRail(b) {
  return `<aside class="bn-rail" aria-label="About this being"><dl class="bn-pf"><div><dt>Played by</dt><dd>${b.played ? `<span class="bn-av xs" aria-hidden="true">${esc(initials(personName(b.played)))}</span>` : ''}${esc(personName(b.played))}</dd></div><div><dt>Seen by</dt><dd>${b.seen === 'Everyone' ? '<span class="everyone">Everyone</span>' : bnAud(b.seen)}</dd></div><div><dt>Campaign</dt><dd>${b.campaign ? esc(CAMPAIGNS.find((c) => c.id === b.campaign).n) : 'None'}</dd></div></dl>${isGM() ? `<button type="button" class="btn" data-bn="handover">${ic('handoff')}<span>Hand over</span></button>` : ''}${isGM() && b.events.length ? `<div><h3 class="t-micro" style="margin:0 0 var(--s-2)">Events</h3><ul class="bn-ev">${b.events.map(([n, k]) => `<li>${esc(n)}<span class="t-meta">${k}</span></li>`).join('')}</ul></div>` : ''}</aside>`;
}
function pBeing() {
  const b = beingOf(parts()[1]);
  if (!b || !canSee(b)) return `<div class="page page--wide page-enter bn"><div class="bn-empty"><p><b>This page does not exist.</b></p><p class="t-meta">The link may be wrong, or the being is not one you can read.</p><a class="btn" href="#/beings">Back to all beings</a></div></div>`;
  const note = '';
  return `<div class="page page--wide page-enter bn bn-page" data-id="${b.id}">${bnHead(b)}${note}${bnBand(b)}<div class="bn-cols"><div class="bn-main" data-mode="${BN.mode}">${bnAbout(b)}${bnNotes(b)}${bnStats(b)}${bnInv(b)}</div>${bnRail(b)}</div></div>`;
}
